{
  "identity": {
    "name": "Crofts Electric (subsidiary of RC Electric LLC)",
    "location": "Boise, Idaho (also operating in Lexington, Kentucky)",
    "claims": [
      {
        "statement": "Crofts Electric is a licensed, family-owned electrical service business operating in Boise, Idaho and surrounding communities.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Crofts Electric is a licensed, family-owned electrician near you in Boise, Idaho with over 16 years of service homeowners, businesses, and construction contractors."
      },
      {
        "statement": "Crofts Electric operates as a subsidiary of RC Electric LLC.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "quote": "Crofts Electric, a subsidiary of RC Electric LLC, currently specializes in five star service and top quality electrical work"
      },
      {
        "statement": "The company was founded by Master Electrician and Licensed Contractor [redacted] in Lexington, Kentucky and expanded to Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "quote": "[redacted], Master Electrician and Licensed Contracto r, opened Crofts Electric after achieving 14 years of advanced training and work experience."
      },
      {
        "statement": "In Idaho, the company serves Boise, Eagle, Nampa, Meridian, Star, and Garden City.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "We offer free and honest written estimates and fairly priced electrical services in Boise, Eagle, Nampa, Meridian, Star, and Garden City, ID."
      }
    ]
  },
  "industry": {
    "industry": "Electrical Contracting (Residential, Commercial, Construction, and Property Management)",
    "activities": [
      "Electrical panel and service upgrades",
      "Residential and commercial electrical repairs and troubleshooting",
      "EV charging station installations",
      "Whole-home natural gas standby generator installations",
      "Smart home technology and security camera (Ring) installations",
      "New construction, kitchen remodeling, and commercial space fit-out electrical work",
      "Property management and Realtor pre-listing electrical code compliance services",
      "Building Automation Systems (BAS) and Building Energy Management Systems (BEMS) installations"
    ],
    "claims": [
      {
        "statement": "Crofts Electric provides residential and commercial electrical panel upgrades, circuit breaker repair, EV charger installations, smart home installations, standby generators, and remodeling work.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "We provide a wide range of residential and commercial electrical services including electrical panel upgrades , circuit breaker repair and replacement , EV charger installations"
      },
      {
        "statement": "The company performs electrical work for property management companies and Realtors.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/property-management-real-estate-electricians",
        "quote": "[redacted]’ electricians can perform complex wiring, circuitry routing, and lighting design for properties under your management."
      },
      {
        "statement": "The company installs Building Automation Systems (BAS), Building Energy Management Systems (BEMS), smart building systems, and security systems for construction projects.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "We also specialize in Building Automation Systems (BAS), Building Energy Management Systems (BEMS), smart building systems, security systems, and EV charging system installations ."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.croftselectricboise.com/",
    "claims": [
      {
        "statement": "Crofts Electric's stated business hours in Boise are Monday through Friday, 8:00 AM to 4:30 PM, and its phone number is [redacted].",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Available Monday–Friday, 8am–4:30pm · Call [redacted]"
      },
      {
        "statement": "The company states that every electrician on its team is a certified journeyman or master electrician.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Every electrician on our team is a certified journeyman or master electrician."
      },
      {
        "statement": "Crofts Electric offers free written estimates, a 15% discount on initial service call labor for new customers, and a 10% discount for seniors, first responders, and active military.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "New customers receive a 15% discount on initial service call labor, and seniors, first responders, and active military receive a 10% discount on electrical services."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Crofts Electric lists Idaho Master Electrician License #CE061542 and Idaho Electrical Contractor License #ME059080 on its website.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "Yes. Crofts Electric holds an Idaho Master Electrician License #CE061542 and Idaho Electrical Contractor License #ME059080 ."
      },
      {
        "statement": "The website footer also lists Kentucky Master Electrician License #CE65316 and Kentucky Electrical Contractor License #ME65337.",
        "label": "fact",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": "KY MASTER ELECTRICIAN LICENSE #CE65316 KY KY ELECTRICAL CONTRACTOR LICENSE #ME65337 ID MASTER ELECTRICIAN LICENSE #CE061542 ID ELECTRICAL CONTRACTOR LICENSE #ME059080"
      }
    ],
    "limitations": "License numbers are stated on the company's website; independent verification against state licensing registries in Idaho and Kentucky cannot be performed from the company's site alone."
  },
  "existingSoftware": [
    {
      "product": "Squarespace (crofts-electric-boise.squarespace.com / assets.squarespace.com)",
      "purpose": "Website content management system, hosting, and native web contact form component",
      "evidence": {
        "statement": "The website loads scripts from assets.squarespace.com and definitions.sqspcdn.com, references crofts-electric-boise.squarespace.com, and loads website.components.form.visitor.js on the contact page.",
        "label": "inference",
        "sourceUrl": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
        "quote": null
      }
    },
    {
      "product": "Google Tag Manager / Google Ads tag (googletagmanager.com/gtag/js?id=AW-805112476)",
      "purpose": "Advertising tag and conversion/analytics tracking on secondary pages",
      "evidence": {
        "statement": "The About, Contact, Discounts, and Property Management pages load https://www.googletagmanager.com/gtag/js?id=AW-805112476.",
        "label": "inference",
        "sourceUrl": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
        "quote": null
      }
    },
    {
      "product": "Elfsight widget platform (apps.elfsight.com/p/platform.js)",
      "purpose": "Third-party embedded website widget on the homepage",
      "evidence": {
        "statement": "The homepage loads https://apps.elfsight.com/p/platform.js.",
        "label": "inference",
        "sourceUrl": "https://www.croftselectricboise.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company states its availability is Monday through Friday from 8:00 AM to 4:30 PM and directs visitors to call [redacted].",
      "label": "fact",
      "sourceUrl": "https://www.croftselectricboise.com/",
      "quote": "Available Monday–Friday, 8am–4:30pm · Call [redacted]"
    },
    {
      "statement": "The Contact page directs prospective customers to use a standard web form or call by phone, with no online scheduling, live chat widget, or automated instant-response tool observable on the site.",
      "label": "fact",
      "sourceUrl": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
      "quote": "We look forward to hearing from you! Use the form below to contact us, or give us a call."
    },
    {
      "statement": "The presence of the AW-805112476 tag on the Contact, Discounts, and About pages indicates the company has configured paid advertising tracking.",
      "label": "inference",
      "sourceUrl": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
      "quote": null
    },
    {
      "statement": "The company operates across two geographic markets (Lexington, Kentucky and Boise, Idaho), which may require routing and tracking leads and estimates across multiple locations.",
      "label": "inference",
      "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
      "quote": null
    },
    {
      "statement": "Phone numbers on the website appear as plain text rather than clickable tel: links, and the homepage does not load the AW-805112476 tag that is present on inner pages.",
      "label": "inference",
      "sourceUrl": "https://www.croftselectricboise.com/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "After-hours, weekend, and overflow phone inquiries outside the 8:00 AM–4:30 PM Monday–Friday window, as well as web form submissions, may experience delayed follow-up if handled manually.",
      "label": "hypothesis",
      "basis": "The site lists office hours of Monday–Friday, 8am–4:30pm and relies on phone calls and a standard Squarespace contact form without observable automated instant-reply or online booking tools."
    },
    {
      "problem": "Written estimates across residential, commercial, and property-management jobs may lack systematic follow-up tracking, potentially allowing open quotes to go cold.",
      "label": "hypothesis",
      "basis": "The company emphasizes free written estimates and multi-segment discounts (15% new client, 10% repeat/senior/military), which often involve manual quote follow-up unless managed in a field-service CRM."
    },
    {
      "problem": "Owner visibility into marketing return on investment and lead conversion by source across Boise and Lexington may be fragmented.",
      "label": "hypothesis",
      "basis": "The site loads a Google tag (AW-805112476) on inner pages, but not on the homepage, and has no visible call-tracking scripts or clickable tel: links."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Off-the-shelf Field Service Management (FSM) software (such as Housecall Pro, Jobber, or ServiceTitan)",
      "addresses": "Provides built-in online booking, automated lead intake, missed-call text-back, estimate follow-up sequences, and basic reporting.",
      "alreadyOwned": false
    },
    {
      "solution": "Squarespace native form notifications and email autoresponders",
      "addresses": "Sends basic confirmation emails when a visitor submits the Contact page form.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "One-week audit ($500 fixed price, credited toward any fix ordered within 30 days) measuring how many calls, web form leads, and written estimates slip through after 4:30 PM or during busy dispatch hours.",
      "problem": "Potential uncaptured calls, delayed web form responses, and unfollowed written estimates.",
      "whyNotExistingSoftware": "Before buying or reconfiguring software, a quick diagnostic establishes whether a real revenue leak exists and whether the company's current back-office tools already have unused automation features."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Automated pipeline ($1,800 setup plus $149/month) that captures Squarespace form submissions and missed calls within two minutes, sends an instant SMS/email acknowledgment, and creates a tracked follow-up task in their field-service software.",
      "problem": "Delayed response to web form leads and after-hours/overflow calls outside the 8:00 AM–4:30 PM weekday window.",
      "whyNotExistingSoftware": "Squarespace forms do not natively push structured job leads into field-service software with instant SMS reply and persistent callback reminders without custom integration."
    },
    {
      "name": "Owner's Monday numbers",
      "kind": "catalog",
      "description": "Weekly one-page summary ($1,200 setup plus $99/month) consolidating booked revenue, close rate on written estimates, average ticket, cost per booked job by lead source, and accounts receivable across operations.",
      "problem": "Fragmented visibility into ad spend performance, estimate close rates, and receivables across residential and commercial work.",
      "whyNotExistingSoftware": "Standard field-service software, accounting software, and ad accounts rarely combine cost-per-booked-job and receivables into a single cross-system weekly digest without custom data integration."
    }
  ],
  "feasibility": {
    "rating": "medium",
    "explanation": "Integrating Squarespace form submissions and call/SMS workflows is straightforward, but overall technical feasibility depends on what field-service management and accounting software Crofts Electric uses internally, which is not observable on the public website."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "Deterministic workflow automation handles lead capture, instant SMS/email replies, and weekly metrics aggregation reliably, while AI agents can assist with classifying incoming project descriptions (e.g., panel upgrade vs. commercial fit-out vs. property management work order) and drafting initial replies."
  },
  "humanReview": [
    "All written electrical estimates, pricing, and scope assessments must be reviewed and approved by a licensed electrician.",
    "Code-compliance determinations, load calculations (such as EV chargers, standby generators, and sub-panels), and commercial bidding require direct human oversight.",
    "Non-routine customer inquiries or emergency electrical safety issues must be routed immediately to qualified staff rather than handled by automated replies."
  ],
  "risks": [
    {
      "type": "compliance",
      "description": "Automated SMS or phone follow-ups to leads must comply with TCPA consent requirements and state telemarketing rules."
    },
    {
      "type": "operational",
      "description": "An automated assistant or intake workflow must never give DIY electrical troubleshooting advice or imply that an electrical hazard is safe to ignore."
    },
    {
      "type": "security",
      "description": "Customer contact details, property addresses, and access instructions from property managers or Realtors must be transmitted and stored securely with minimal access."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": "Revenue Leak Check: $500 fixed price (credited in full toward any fix ordered within 30 days); Lead-to-job pipeline: $1,800 setup plus $149/month; Owner's Monday numbers: $1,200 setup plus $99/month.",
    "assumptions": [
      "The website states percentage discounts (15% off initial service call labor for new customers; 10% off for repeat customers, seniors, first responders, and active military) but publishes no dollar prices or service call fees, so illustrative commercial value cannot be calculated under ForgeX's evidence rules."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Master Electrician & Licensed Contractor",
      "Office Manager / Operations Manager"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Master Electrician and Licensed Contractor / Founder",
        "sourceUrl": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "quote": "[redacted], Master Electrician and Licensed Contracto r, opened Crofts Electric after achieving 14 years of advanced training and work experience."
      }
    ],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.croftselectricboise.com/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How many journeyman and master electricians are currently on the Crofts Electric team across Boise and Lexington?",
      "What field-service software or CRM do you currently use to manage dispatching, written estimates, and invoicing?",
      "When calls come in after 4:30 PM or on weekends—or when a prospect submits the Squarespace contact form—how quickly does someone follow up, and how is that tracked?",
      "Do you already have a process for following up on open written estimates for panel upgrades, EV chargers, and remodeling jobs, or is that done manually?",
      "How are you currently tracking which booked jobs come from Google Ads versus referrals, Realtors, and property managers?"
    ],
    "outreachSubject": "Question about lead & estimate follow-up at Crofts Electric",
    "outreachBody": "Hi [redacted],\n\nI was looking at Crofts Electric's Boise website and noticed you handle everything from residential panel upgrades and EV chargers to property management and commercial fit-outs, with office hours running Monday–Friday, 8:00 AM to 4:30 PM.\n\nAt ForgeX, we work with owner-led electrical and home-service contractors on fixed-price workflow automations—such as routing web form leads and after-hours inquiries into your field-service software with an instant reply, or tracking open written estimates and ad-spend ROI in a one-page Monday summary.\n\nBefore recommending anything, we always check whether your existing software already covers what you need. If you don't already have automated lead intake and estimate follow-up in place, we also offer a 1-week Revenue Leak Check ($500 fixed price, credited in full toward any fix you order within 30 days) to measure whether any calls, leads, or written estimates are slipping through.\n\nWould you be open to a brief 10-minute call to see if this is relevant to your Boise and Lexington operations?\n\nBest regards,\n\n[Founder Name]\n[Founder Title], ForgeX\n[ForgeX Phone Number]\n[ForgeX Physical Postal Address]\n\nIf you prefer not to receive future emails from us, simply reply with \"unsubscribe\" or use [Opt-Out Link] and we will remove you right away."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.croftselectricboise.com/",
        "usedFor": "Business identity, Boise service area, hours of operation, phone number, Idaho and Kentucky license numbers, services offered, discount offers, and homepage script/host analysis."
      },
      {
        "url": "https://www.croftselectricboise.com/about-crofts-electric-boise-idaho-history-electricians",
        "usedFor": "Founder identity ([redacted]), parent entity (RC Electric LLC), company history in Lexington, KY and expansion to Boise, ID, and Google tag script evidence."
      },
      {
        "url": "https://www.croftselectricboise.com/our-expert-boise-electricians-skills-qualifications",
        "usedFor": "Workforce qualification policy (journeyman and master electricians only)."
      },
      {
        "url": "https://www.croftselectricboise.com/contact-electrical-repairs-services-free-estimate",
        "usedFor": "Lead intake mechanism (Squarespace form and phone call), service categories, and Google tag script evidence."
      },
      {
        "url": "https://www.croftselectricboise.com/boise-idaho-electrical-electrician-services-discounts",
        "usedFor": "Discount structures (15% new customer labor discount, 10% repeat/senior/first responder/military discount) and confirmation that no dollar prices are published."
      },
      {
        "url": "https://www.croftselectricboise.com/property-management-real-estate-electricians",
        "usedFor": "B2B property management and real estate electrical service details."
      }
    ],
    "limitations": [
      "The website does not disclose the total employee headcount of Crofts Electric (whether it falls within the 10–75 staff target range).",
      "Internal back-office software (such as field-service management, dispatching, or accounting systems) cannot be observed from the public website.",
      "The website publishes percentage discounts (10% and 15%) but no dollar prices or service call rates, preventing a quantitative commercial value calculation.",
      "The linked page https://www.croftselectricboise.com/trusted-experts-boise-electricians-lexington-electricians returned HTTP 404 (not found).",
      "No business email address or physical street address is published on the pages read."
    ]
  },
  "qualification": {
    "category": "pursue later",
    "rationale": "Crofts Electric is an owner-led electrical contractor ([redacted]) operating in Boise, ID and Lexington, KY with evidence of paid ad tracking (gtag AW-805112476), a clear business phone channel ([redacted]), weekday-only stated hours (Monday–Friday, 8am–4:30pm), and a standard Squarespace contact form with no visible online booking or automated lead capture on the site. However, staff headcount (10–75 employees) is unconfirmed on the website, and operational problems such as missed after-hours calls or unfollowed written estimates remain hypotheses rather than confirmed facts on the site."
  }
}
